```python
def longest_common_subsequence(str1: str, str2: str) -> str:
    # Initialize a 2D array to store the LCS lengths
    lcs_lengths = [[0] * len(str2) for _ in range(len(str1))]

    # Fill in the diagonal with 1s, as one-long subsequences are trivially equal to themselves
    for i, c in enumerate(str1):
        if c == str2[i]:
            lcs_lengths[i][i] = 1

    # Find the LCS length by summing up previous common elements, keeping a rolling max
    for j in range(1, len(str2)):
        current_lcs_length = 0
        for I in range(1, len(str1)):
            if str1[i - 1] == str2[j - 1]:
                current_lcs_length += 1
                lcs_lengths[i][j] = max(lcs_lengths[i][j], current_lcs_length)
            elif lcs_lengths[i - 1][j - 1] > 0:
                lcs_lengths[i][j] = max(lcs_lengths[i][j], lcs_lengths[i - 1][j - 1])
            else:
                break

    # Reconstruct the path that forms the LCS from the table, backwards
    i, j = len(str1) - 1, len(str2) - 1
    lcs = ""
    while I >= 0 and j >= 0:
        if I < len(str1) - 1 and j < len(str2) - 1:
            if str1[i + 1]!= str2[j + 1]:
                if lcs_lengths[i - 1][j - 1] > lcs_lengths[i][j]:
                    I -= 2
                    j -= 2
                    lcs = [str2[j]] + lcs
                else:
                    i -= 1
                    lcs = [str1[i]] + lcs
            else:
                I -= 1
                j -= 1
                lcs = [str1[i]] + lcs
        elif I >= len(str1) - 1:
            I -= 1
            lcs = [str1[i]] + lcs
        else:
            j -= 1
            lcs = [str2[j]] + lcs
    return lcs[::-1]
```

